public static double factorial(int n) {

    double resultado = 1;

    for (int i = 1; i <= n; i++) {
        resultado = resultado * i;
    }

    return resultado;
}

// Recursivo
public static double factorialRecursivo(int n) {

    if(n == 0)
        return 1;
    else
        return  n * factorialRecursivo(n-1);

}

