// Iterativo
private static int fibonacci(int n) {

    int siguiente = 1, actual = 0, temporal = 0;

    for (int i = 1; i <= n; i++) {
        temporal = actual;
        actual = siguiente;
        siguiente = siguiente + temporal;
    }

    return actual;

}

// Recursivo
private static int fibonacciRecursivo(int n) {
    if (n <= 2) {
        return 1;
    } else {
        return fibonacciRecursivo(n - 1) + fibonacciRecursivo(n - 2);
    }
}

