private static int par(int num) {
    if (num == 0)
        return (1);
    return (impar(num - 1));
}

private static int impar(int num) {
    if (num == 0)
        return (0);
    return (par(num - 1));
}

private static int ackermann(int n, int m) {
    if (n == 0)
        return (m + 1);
    else if (m == 0)
        return (ackermann(n - 1, 1));
    return (ackermann(n - 1, ackermann(n, m - 1)));
}

